<script>
  import { onMount, onDestroy } from 'svelte';
  import { nbaCalendarUrl, nbaCalendarRows } from '$lib/product/calendar.js';
  let dayIndex=0, search='', games=[], selectedId=null, loading=true, unavailable=false, fetchedAt=null, mounted=false, signature=-1;
  let controller, generation=0;
  $: filtered=games.filter(game=>`${game.home_team.full_name} ${game.visitor_team.full_name}`.toLocaleLowerCase('es').includes(search.trim().toLocaleLowerCase('es')));
  $: selected=filtered.find(game=>game.id===selectedId)||filtered[0];
  $: if(mounted && signature!==dayIndex){signature=dayIndex;load();}
  onMount(()=>{mounted=true;});
  onDestroy(()=>{generation++;controller?.abort();});
  async function load(){
    const run=++generation;controller?.abort();controller=new AbortController();
    loading=true;unavailable=false;games=[];selectedId=null;fetchedAt=null;
    try{
      const response=await fetch(nbaCalendarUrl(Date.now(),dayIndex),{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(15000)])});
      const body=await response.json();const rows=nbaCalendarRows(response,body);
      if(run===generation){games=rows;fetchedAt=new Date();}
    }catch{if(run===generation)unavailable=true;}
    finally{if(run===generation)loading=false;}
  }
  function readableStatus(game){
    const value=game.status||'';
    if(value==='Final')return 'Finalizado';
    const timestamp=Date.parse(value);
    if(value.includes('T')&&Number.isFinite(timestamp))return new Intl.DateTimeFormat('es',{hour:'2-digit',minute:'2-digit',timeZone:'America/New_York'}).format(timestamp)+' · NY';
    return value||'Horario sin confirmar';
  }
  const context=[{n:'01',title:'Ritmo y anotación',text:'Revisa los puntos por periodo y la diferencia entre jugar como local o visitante.'},{n:'02',title:'Situación del equipo',text:'Contrasta descansos y ausencias con fuentes. Un dato sin confirmar sigue siendo desconocido.'},{n:'03',title:'Línea y probabilidad',text:'Compara la estimación con la línea del mercado. Una proyección no garantiza el resultado.'}];
</script>

<div class="nba">
  <a class="back" href="/sports">← Todos los deportes</a>
  <header class="nba-hero"><div class="hero-copy"><span class="eyebrow">NIOSPORTS / BASKETBALL LAB</span><h1>Entiende el ritmo.<br/><em>Lee el partido.</em></h1><p>Equipos, calendario y contexto. Tu centro de análisis NBA, desde la primera posesión hasta el último cuarto.</p><a class="hero-cta" href="/totales">Abrir análisis de totales <span>↗</span></a></div><div class="court-art" aria-hidden="true"><svg viewBox="0 0 340 260" fill="none"><rect x="22" y="20" width="296" height="220" rx="3"/><path d="M170 20v220"/><circle cx="170" cy="130" r="34"/><path d="M22 76h68v108H22M318 76h-68v108h68"/><path d="M22 40a100 100 0 0 1 0 180M318 40a100 100 0 0 0 0 180"/><circle cx="50" cy="130" r="9"/><circle cx="290" cy="130" r="9"/></svg><span class="ball"></span><small>Q1 / HALF / FULL</small></div></header>
  <div class="section-head"><div><span class="eyebrow">EL CALENDARIO</span><h2>Tu próxima lectura.</h2></div><span class="zone">Hora y fecha de Nueva York</span></div>
  <div class="toolbar"><div class="days" role="group" aria-label="Día NBA"><button class:active={dayIndex===0} aria-pressed={dayIndex===0} on:click={()=>dayIndex=0}>Hoy</button><button class:active={dayIndex===1} aria-pressed={dayIndex===1} on:click={()=>dayIndex=1}>Mañana</button></div><label class="search"><span>Buscar equipo</span><input type="search" bind:value={search} placeholder="Lakers, Celtics…"/></label><button class="refresh" on:click={load} disabled={loading}>{loading?'Consultando…':'Actualizar calendario'}</button></div>
  {#if loading}<div class="empty" role="status"><div class="loader"></div><h3>Consultando la jornada.</h3><p>Estamos comprobando el calendario del proveedor.</p></div>
  {:else if unavailable}<div class="empty" role="alert"><span class="empty-icon" aria-hidden="true">↗</span><h3>La jornada necesita una fuente disponible.</h3><p>No pudimos confirmar los partidos. Puedes reintentar o consultar cómo se construye el análisis mientras se restablece la información.</p><div class="empty-actions"><button on:click={load}>Reintentar consulta</button><a href="/methodology">Conocer la metodología ↗</a></div></div>
  {:else}
    <div class="source"><span>Fuente: BALLDONTLIE · Consultado {fetchedAt?.toLocaleTimeString('es',{hour:'2-digit',minute:'2-digit'})}</span><span>{filtered.length} partidos en esta vista</span></div>
    {#if filtered.length===0}<div class="empty"><h3>{search?'Ningún equipo coincide con tu búsqueda.':'Sin encuentros en el calendario recibido.'}</h3><p>{search?'Prueba con otro equipo o limpia la búsqueda.':'La cobertura recibida no contiene partidos para el día seleccionado.'}</p>{#if search}<button on:click={()=>search=''}>Limpiar búsqueda</button>{/if}</div>
    {:else}<div class="workspace"><aside class="schedule" aria-label="Partidos NBA">{#each filtered as game(game.id)}<button class="match" class:selected={selected?.id===game.id} aria-pressed={selected?.id===game.id} on:click={()=>selectedId=game.id}><span class="match-status">{readableStatus(game)}</span><strong>{game.visitor_team.full_name}</strong><span class="match-vs">visita a</span><strong>{game.home_team.full_name}</strong><span class="match-foot">Ver contexto <b>↗</b></span></button>{/each}</aside><section class="report" aria-label="Contexto del partido"><div class="report-top"><span class="eyebrow">EL ENCUENTRO</span><span>{readableStatus(selected)}</span></div><div class="versus"><div><span class="team-mark">{selected.visitor_team.abbreviation||'V'}</span><small>VISITANTE</small><h3>{selected.visitor_team.full_name}</h3></div><b class="vs">VS</b><div><span class="team-mark home-team">{selected.home_team.abbreviation||'L'}</span><small>LOCAL</small><h3>{selected.home_team.full_name}</h3></div></div>{#if selected.status==='Final'&&Number.isFinite(selected.visitor_team_score)&&Number.isFinite(selected.home_team_score)}<p class="score">Resultado final <strong>{selected.visitor_team_score} — {selected.home_team_score}</strong></p>{/if}<div class="context-note"><h3>El calendario es el punto de partida.</h3><p>Abre la calculadora y selecciona estos equipos para consultar los datos disponibles por periodo. Las cuotas, lesiones y descansos requieren confirmación aparte.</p></div><a class="analysis-link" href="/totales">Abrir calculadora de totales ↗</a></section></div>{/if}
  {/if}
  <section class="analysis-section"><div class="section-head"><div><span class="eyebrow">DEL PARTIDO AL ANÁLISIS</span><h2>Los detalles que dan contexto.</h2></div><a href="/picks">Mis pronósticos NBA ↗</a></div><div class="context-grid">{#each context as item}<article><span class="step">{item.n}</span><h3>{item.title}</h3><p>{item.text}</p></article>{/each}</div></section>
  <div class="analysis-bottom"><div><h3>Una línea. Tres perspectivas.</h3><p>Primer cuarto, primera mitad y partido completo: explora cada periodo dentro de la calculadora.</p></div><a href="/totales">Analizar totales ↗</a></div>
</div>

<style>
 .nba{--ink:#edf2fa;--muted:#b8c3d5;--surface:#131e30;--raised:#1c2a40;--line:#36445c;--accent:#efba86;--selection:#372b25;max-width:1280px;margin:auto;padding:26px 32px 90px;color:var(--ink);font-family:var(--font-sans);position:relative;font-variant-numeric:tabular-nums}
 :global([data-theme="light"]) .nba{--ink:#152a45;--muted:#52637a;--surface:#fff;--raised:#f0f4fa;--line:#c7d3e0;--accent:#8c4d1d;--selection:#fcf0e5}
