ius:9px;background:var(--surface)}button{border:1px solid var(--line);border-radius:7px;background:var(--surface);padding:10px 15px;font-size:13px;min-height:44px}button:hover{border-color:var(--accent)}button:disabled{opacity:.6;cursor:wait}.days button{border:0;background:transparent;color:var(--muted);min-width:80px}.days .active{background:var(--selection);color:var(--accent);font-weight:700}.search{display:flex;align-items:center;gap:10px;background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:0 12px}.search span{font-size:12px;color:var(--muted)}.search input{min-width:100px;width:180px;padding:10px 0;background:transparent;border:0;color:var(--ink);font-size:14px}.search input::placeholder{color:var(--muted);opacity:1}.refresh{margin-left:auto}.empty{border:1px solid var(--line);background:var(--surface);border-radius:14px;text-align:center;padding:42px 24px}.empty-icon{display:grid;place-items:center;width:46px;height:46px;border:1px solid var(--line);border-radius:50%;margin:0 auto 18px;color:var(--accent);font-size:25px}.empty h3{font-size:22px}.empty p{font-size:14px;color:var(--muted);max-width:550px;line-height:1.8;margin:14px auto 20px}.empty-actions{display:flex;align-items:center;justify-content:center;gap:22px;flex-wrap:wrap}.empty-actions a{font-size:13px;color:var(--accent)}.loader{height:26px;width:26px;border:2px solid var(--line);border-top-color:var(--accent);border-radius:50%;margin:0 auto 18px;animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.source{display:flex;justify-content:space-between;gap:15px;margin-bottom:15px;color:var(--muted);font-size:12px}.workspace{display:grid;grid-template-columns:290px minmax(0,1fr);gap:20px}.schedule{display:flex;flex-direction:column;gap:10px;max-height:620px;overflow:auto}.match{display:flex;flex-direction:column;text-align:left;padding:20px;flex-shrink:0}.match.selected{background:var(--selection);border-color:var(--accent)}.match-status{font-size:12px;color:var(--muted);margin-bottom:16px}.match strong{font-size:15px}.match-vs{font-size:12px;color:var(--muted);margin:5px 0}.match-foot{display:flex;justify-content:space-between;align-items:center;width:100%;font-size:12px;padding-top:14px;margin-top:15px;border-top:1px solid var(--line);color:var(--accent)}.report{padding:28px;border:1px solid var(--line);border-radius:14px;background:var(--surface);min-width:0}.report-top{display:flex;justify-content:space-between;gap:14px;color:var(--muted);font-size:12px}.versus{display:grid;grid-template-columns:1fr 40px 1fr;gap:12px;text-align:center;align-items:center;padding:30px 0}.team-mark{display:grid;place-items:center;width:66px;height:66px;border-radius:20px;background:var(--raised);color:var(--ink);font-size:20px;font-weight:700;margin:0 auto 14px}.home-team{background:var(--selection);color:var(--accent)}.versus small{font-size:11px;color:var(--muted)}.versus h3{font-size:20px;margin-top:10px}.vs{font-size:12px;color:var(--muted)}.score{text-align:center;color:var(--muted);font-size:13px}.score strong{display:block;font-size:30px;color:var(--ink);margin-top:8px}.context-note{border-top:1px solid var(--line);padding-top:22px;margin-top:10px}.context-note h3{font-size:17px}.context-note p{font-size:14px;line-height:1.8;color:var(--muted);margin:10px 0 20px}.analysis-link{display:flex;align-items:center;justify-content:center;min-height:48px;border:1px solid var(--line);border-radius:8px;color:var(--accent);font-size:14px;font-weight:700}.context-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.context-grid article{border:1px solid var(--line);border-radius:12px;padding:25px;background:var(--surface)}.step{display:block;color:var(--accent);font-size:12px;margin-bottom:24px}.context-grid h3{font-size:18px}.context-grid p,.analysis-bottom p{color:var(--muted);font-size:14px;line-height:1.8;margin-top:12px}.analysis-bottom{display:flex;justify-content:space-between;align-items:center;gap:24px;padding:28px;border-left:3px solid var(--accent);background:var(--raised);border-radius:0 12px 12px 0;margin-top:24px}.analysis-bottom h3{font-size:21px}.analysis-bottom a{color:var(--accent);font-size:14px;white-space:nowrap}
 @media(max-width:760px){.nba{padding:20px 16px 90px}.nba-hero{padding:27px;grid-template-columns:1fr}.court-art{display:none}.section-head{align-items:start;flex-direction:column;gap:12px}.search{flex:1}.search input{width:100%}.refresh{margin-left:0}.workspace,.context-grid{grid-template-columns:1fr}.schedule{max-height:300px}.report{padding:20px}.versus{gap:8px;grid-template-columns:1fr 24px 1fr}.versus h3{font-size:17px}.analysis-bottom{align-items:start;flex-direction:column}.source{flex-direction:column}.toolbar{gap:12px}.toolbar .search{flex-basis:100%}}
